import { useState } from "react";

import "./Contact.scss";

function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    subject: "",
    message: "",
  });

  const handleChange = (event) => {
    setForm({
      ...form,
      [event.target.name]: event.target.value,
    });
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    const body = `
Name: ${form.name}

Email: ${form.email}

Message:
${form.message}
`;

    window.location.href =
      `mailto:handersonmoses360@gmail.com` +
      `?subject=${encodeURIComponent(
        form.subject || "Portfolio Contact"
      )}` +
      `&body=${encodeURIComponent(body)}`;
  };

  return (
    <section className="contact section" id="contact">

      <div className="contact-text reveal">

        <h2>
          Contact <span>Me</span>
        </h2>

        <h4>Let's Work Together</h4>

        <p>
          I am looking for opportunities where I
          can contribute as a Web Developer,
          Python Developer, or AI/ML Developer.
        </p>

        <ul className="contact-list">

          <li>
            <i className="bx bxs-send"></i>

            <a href="mailto:handersonmoses360@gmail.com">
              handersonmoses360@gmail.com
            </a>
          </li>

          <li>
            <i className="bx bxs-phone"></i>

            <a href="tel:9361730447">
              9361730447
            </a>
          </li>

        </ul>

        <div className="contact-icon">

          <a href="mailto:handersonmoses360@gmail.com">
            <i className="bx bxl-gmail"></i>
          </a>

          <a
            href="https://www.linkedin.com/in/moses-raj-b10525233/"
            target="_blank"
            rel="noreferrer"
          >
            <i className="bx bxl-linkedin"></i>
          </a>

          <a
            href="https://github.com/Moses360-co"
            target="_blank"
            rel="noreferrer"
          >
            <i className="bx bxl-github"></i>
          </a>

        </div>

      </div>

      <form
        className="contact-form reveal"
        onSubmit={handleSubmit}
      >

        <input
          type="text"
          name="name"
          placeholder="Enter Your Name"
          value={form.name}
          onChange={handleChange}
          required
        />

        <input
          type="email"
          name="email"
          placeholder="Enter Your Email"
          value={form.email}
          onChange={handleChange}
          required
        />

        <input
          type="text"
          name="subject"
          placeholder="Enter Your Subject"
          value={form.subject}
          onChange={handleChange}
        />

        <textarea
          name="message"
          placeholder="Enter Your Message"
          value={form.message}
          onChange={handleChange}
          required
        />

        <button type="submit">
          Send Message
        </button>

      </form>

    </section>
  );
}

export default Contact;
